// HelloLoop.jsx — LAB 01·A, the book's first Bench (Ch 1, DESIGN §3 + §6.1).
//
// Left pane: the dependency-patch benchfile, the house notation. Right pane:
// the run, generated by the loopstep engine and replayed step by step. The
// control bar grammar (Step · Run · Reset · Fork) is established here and
// never varied book-wide. Fork 1 turns the oracle red (close-on-red,
// reversibility working). Fork 2 deletes the update: stanza, takes a
// committed prediction, then draws the amnesia bill: two review-cost lines
// over ten weeks, one falling, one flat.
//
// Mechanism register: every trace here is the engine's real dynamics,
// recorded. Seed 1, deterministic forever.

import { useEffect, useState } from 'react';
import { Artifact, Badge, Commit, LabFrame, Mark, glassSlice } from '../components/kit.jsx';
import { usePrefersReducedMotion } from '../shared/usePrefersReducedMotion.js';
import { amnesiaComparison, canonicalRun, redRun } from '../engine/scenarios/helloLoop.js';
import loopstepSrc from '../engine/loopstep.js?raw';

/* ── The recorded runs (module-level: same seed, same trace, forever) ──── */

const SEED = 1;
const CANONICAL = canonicalRun(SEED);
const RED = redRun(SEED);
const AMNESIA = amnesiaComparison(SEED);

const CLOSING_COST = AMNESIA.steps[0].data.closing.series.reviewCost;
const AMNESIAC_COST = AMNESIA.steps[0].data.amnesiac.series.reviewCost;
const FINALE = AMNESIA.steps.at(-1).data; // { billMinutes, relitigated, totals }

const WEEK1 = Math.round(CLOSING_COST[0]);
const WEEK10 = Math.round(CLOSING_COST.at(-1));
const AMN_WEEK = Math.round(AMNESIAC_COST[0]);

// Which simulated week each amnesia-trace step has reached, for the chart.
const AMNESIA_WEEK_AT_STEP = [1, 1, 5, 10];

const sum = (xs) => xs.reduce((a, b) => a + b, 0);

const GLASS = [
  glassSlice(loopstepSrc, 'export function stepStage', '\n}'),
  glassSlice(loopstepSrc, 'function stepWeek(state, config, rng)', '\n}'),
].join('\n\n// ── and ten weeks of it, one week at a time ──\n\n');

/* ── The artifact pane ─────────────────────────────────────────────────── */

// Which benchfile lines each stage of the run is reading. Stage 4 (commit)
// has no stanza on green: the merge is a trace event. On red it is line 9.
const HOT_BY_STAGE = [[2, 3, 4], [5, 6], [7, 8], [], [10, 11, 12]];

function hotLinesFor(mode, idx) {
  if (mode === 'amnesia') return [];
  if (idx === 3 && mode === 'red') return [9];
  return HOT_BY_STAGE[idx] ?? [];
}

function benchfileLines(mode, hot) {
  const deleted = mode === 'amnesia';
  const line = (no, text, kind, annot) => ({ no, text, kind, hot: hot.includes(no), annot });
  return [
    line(1, 'loop: dependency-patch', 'key'),
    line(2, 'signal:', 'key'),
    line(3, '  watch: deps.outdated(level: patch)'),
    line(4, '  fires_when: changelog == clean'),
    line(5, 'action:', 'key'),
    line(6, '  scope: one bump per PR, lockfile only'),
    line(7, 'verification:', 'key'),
    line(8, '  oracle: target repo CI', undefined, 'outside the loop'),
    line(9, 'on_red: close + comment + delete branch', 'key'),
    deleted
      ? { no: 10, text: 'update:', kind: 'comment', annot: 'fork 2 deleted this stanza' }
      : line(10, 'update:', 'key'),
    deleted
      ? { no: 11, text: '  record: {merged, reverted, closed} -> track record', kind: 'comment' }
      : line(11, '  record: {merged, reverted, closed} -> track record'),
    deleted
      ? { no: 12, text: '  decay: 90-day window', kind: 'comment' }
      : line(12, '  decay: 90-day window'),
    line(13, 'authority:', 'key'),
    line(14, '  gate: propose-only', undefined, 'earned auto-merge later'),
  ];
}

/* ── The run pane: software-native snapshot + captions ─────────────────── */

function snapshotAt(steps, idx) {
  const snap = {
    signal: null,
    pr: null,
    prState: null,
    ci: null,
    comment: null,
    branchDeleted: false,
    ledger: null,
  };
  for (let k = 0; k <= idx && k < steps.length; k++) {
    for (const e of steps[k].data.effects ?? []) {
      if (e.type === 'signal-fired') snap.signal = e;
      else if (e.type === 'open-pr') {
        snap.pr = e;
        snap.prState = 'open';
      } else if (e.type === 'ci-run') snap.ci = e.result;
      else if (e.type === 'merge-pr') snap.prState = 'merged';
      else if (e.type === 'close-pr') snap.prState = 'closed';
      else if (e.type === 'comment') snap.comment = e.body;
      else if (e.type === 'delete-branch') snap.branchDeleted = true;
      else if (e.type === 'record-outcome') snap.ledger = e;
    }
  }
  return snap;
}

const PR_CHIP = {
  open: { label: 'OPEN', color: 'var(--blue)' },
  merged: { label: 'MERGED', color: 'var(--accent-ink)' },
  closed: { label: 'CLOSED', color: 'var(--red)' },
};

function RunSnapshot({ steps, idx }) {
  const s = snapshotAt(steps, idx);
  const chip = PR_CHIP[s.prState];
  return (
    <div style={{ display: 'grid', gap: 8, margin: '0 0 10px' }}>
      {s.signal ? (
        <div className="mono" style={{ fontSize: '11.5px', color: 'var(--c-deppatch)' }}>
          signal · {s.signal.watch} — {s.signal.detail}
        </div>
      ) : (
        <div className="mono" style={{ fontSize: '11.5px', color: 'var(--ink-faint)' }}>
          terrain quiet — nothing has fired
        </div>
      )}
      {s.pr ? (
        <div
          style={{
            border: '1px solid var(--line-soft)',
            borderLeft: '3px solid var(--c-deppatch)',
            borderRadius: 3,
            padding: '8px 10px',
            background: 'var(--paper-3)',
          }}
        >
          <div style={{ display: 'flex', gap: 8, alignItems: 'baseline', flexWrap: 'wrap' }}>
            <span className="mono" style={{ fontSize: '12.5px', color: 'var(--ink)' }}>
              {s.pr.title}
            </span>
            <span
              className="mono"
              style={{
                fontSize: '9.5px',
                letterSpacing: '0.12em',
                color: chip.color,
                border: `1px solid ${chip.color}`,
                borderRadius: 3,
                padding: '0 5px',
              }}
            >
              {chip.label}
            </span>
          </div>
          <div
            className="mono"
            style={{
              fontSize: '10.5px',
              color: 'var(--ink-faint)',
              textDecoration: s.branchDeleted ? 'line-through' : 'none',
            }}
          >
            {s.pr.branch}
            {s.branchDeleted ? ' (deleted)' : ''}
          </div>
          {s.comment ? (
            <div
              style={{
                fontSize: '12.5px',
                color: 'var(--ink-2)',
                borderLeft: '2px solid var(--line)',
                paddingLeft: 8,
                marginTop: 6,
              }}
            >
              {s.comment}
            </div>
          ) : null}
        </div>
      ) : null}
      {s.pr ? (
        <span className={'mh-lamp' + (s.ci === 'green' ? ' on' : s.ci === 'red' ? ' off' : '')}>
          target repo CI — {s.ci ?? 'not yet run'}
        </span>
      ) : null}
      {s.ledger ? (
        <div className="mono" style={{ fontSize: '11.5px', color: 'var(--accent-ink)' }}>
          track record · {s.ledger.cls} → {s.ledger.outcome} · decay window 90d
        </div>
      ) : null}
    </div>
  );
}

function StepList({ steps, idx }) {
  return (
    <ol style={{ listStyle: 'none', margin: '10px 0 0', padding: 0 }}>
      {steps.map((step, k) => (
        <li
          key={k}
          className={k === idx ? 'mh-trace-step now' : 'mh-trace-step'}
          aria-current={k === idx ? 'step' : undefined}
        >
          <span className="idx">{k + 1}</span>
          <span className="cap">
            <strong>{step.label}.</strong> {step.caption}
          </span>
        </li>
      ))}
    </ol>
  );
}

/* ── Fork 1: the divergence, beside the original ───────────────────────── */

function DivergenceStrip() {
  return (
    <div className="mh-feedback" style={{ marginTop: 10 }}>
      <span className="mh-kicker" style={{ display: 'block', marginBottom: 6 }}>
        Divergence · stage 4, same artifact
      </span>
      <div className="mono" style={{ fontSize: '12px', display: 'grid', gap: 4 }}>
        <span>
          <span style={{ color: 'var(--accent-ink)' }}>canonical</span> merge-pr — the change lands,
          one revert from undone
        </span>
        <span>
          <span style={{ color: 'var(--red)' }}>this fork</span> close-pr · comment · delete-branch
          — no partial state survives
        </span>
      </div>
      <p style={{ margin: '8px 0 0', fontSize: '13.5px' }}>
        Only the oracle's answer changed; the artifact is untouched. A red costs the terrain one
        comment, because line 9 decided that long before CI ran.
      </p>
    </div>
  );
}

/* ── Fork 2: the amnesia bill, drawn ───────────────────────────────────── */

function AmnesiaChart({ closing, amnesiac, uptoWeek, billMinutes }) {
  const W = 400;
  const H = 200;
  const padL = 44;
  const padR = 100;
  const padT = 14;
  const padB = 32;
  const n = closing.length;
  const yMax = 60;
  const x = (w) => padL + ((w - 1) / (n - 1)) * (W - padL - padR);
  const y = (v) => padT + (1 - v / yMax) * (H - padT - padB);
  const upto = Math.max(1, Math.min(uptoWeek, n));
  const pts = (series) =>
    series
      .slice(0, upto)
      .map((v, i) => `${x(i + 1)},${y(v)}`)
      .join(' ');
  const area =
    upto > 1
      ? [
          ...amnesiac.slice(0, upto).map((v, i) => `${x(i + 1)},${y(v)}`),
          ...closing
            .slice(0, upto)
            .map((v, i) => `${x(i + 1)},${y(v)}`)
            .reverse(),
        ].join(' ')
      : null;
  const ariaLabel =
    `Weekly review minutes over ten weeks. The closing loop falls from ` +
    `${Math.round(closing[0])} to ${Math.round(closing[n - 1])} minutes as its track record ` +
    `accrues; with the update stanza deleted the line stays flat at ` +
    `${Math.round(amnesiac[0])}. The gap between them, summed, is ${billMinutes} steward minutes.`;
  const caption =
    upto < n
      ? `Through week ${upto}: ${Math.round(sum(closing.slice(0, upto)))} steward minutes paid ` +
        `by the closing loop, ${Math.round(sum(amnesiac.slice(0, upto)))} by the amnesiac one.`
      : `The shaded gap, summed: ${billMinutes} steward minutes in ten weeks — the amnesia bill.`;
  return (
    <figure style={{ margin: '12px 0 0' }}>
      <svg
        viewBox={`0 0 ${W} ${H}`}
        role="img"
        aria-label={ariaLabel}
        style={{ width: '100%', height: 'auto', display: 'block' }}
      >
        {[0, 20, 40, 60].map((v) => (
          <g key={v}>
            <line
              x1={padL}
              x2={W - padR}
              y1={y(v)}
              y2={y(v)}
              stroke="var(--line-soft)"
              strokeWidth="1"
            />
            <text
              x={padL - 6}
              y={y(v) + 3.5}
              textAnchor="end"
              fontSize="9"
              fill="var(--ink-faint)"
              fontFamily="var(--font-mono)"
            >
              {v}m
            </text>
          </g>
        ))}
        {[1, 5, 10].map((w) => (
          <text
            key={w}
            x={x(w)}
            y={H - padB + 14}
            textAnchor="middle"
            fontSize="9"
            fill="var(--ink-faint)"
            fontFamily="var(--font-mono)"
          >
            wk {w}
          </text>
        ))}
        {area ? <polygon points={area} fill="var(--red)" opacity="0.07" /> : null}
        {upto > 1 ? (
          <polyline points={pts(amnesiac)} fill="none" stroke="var(--red)" strokeWidth="2" />
        ) : null}
        {upto > 1 ? (
          <polyline points={pts(closing)} fill="none" stroke="var(--accent)" strokeWidth="2" />
        ) : null}
        {amnesiac.slice(0, upto).map((v, i) => (
          <circle
            key={`a${i}`}
            cx={x(i + 1)}
            cy={y(v)}
            r={i === upto - 1 ? 3 : 2}
            fill="var(--red)"
          />
        ))}
        {closing.slice(0, upto).map((v, i) => (
          <circle
            key={`c${i}`}
            cx={x(i + 1)}
            cy={y(v)}
            r={i === upto - 1 ? 3 : 2}
            fill="var(--accent)"
          />
        ))}
        <text
          x={x(upto) + 8}
          y={y(amnesiac[upto - 1]) + 3}
          fontSize="9.5"
          fill="var(--red)"
          fontFamily="var(--font-mono)"
        >
          update: deleted
        </text>
        <text
          x={x(upto) + 8}
          y={y(closing[upto - 1]) + (upto === 1 ? 15 : 3)}
          fontSize="9.5"
          fill="var(--accent-ink)"
          fontFamily="var(--font-mono)"
        >
          closing loop
        </text>
      </svg>
      <figcaption style={{ fontSize: '12.5px', color: 'var(--ink-2)', margin: '6px 0 0' }}>
        {caption}
      </figcaption>
    </figure>
  );
}

const FORK2_OPTIONS = [
  { id: 'nothing', label: 'Nothing changes — no single run looks any different' },
  { id: 'defects', label: 'Defects slip through — update: was part of safety' },
  { id: 'flat', label: 'The bill stops falling — week ten priced like week one' },
];

const FORK2_FEEDBACK = {
  nothing:
    `Right premise; watch the conclusion. No single run looks different — the deletion shows ` +
    `up between runs. Review minutes are priced off the class's track record, and update: was ` +
    `the only stanza writing outcomes back to it. The record freezes at week one, so the bill ` +
    `freezes too: ${AMN_WEEK} minutes a week against the closing loop's ${WEEK10} by week ten. ` +
    `The outcomes never landed back in the terrain as signal; the chart is the difference.`,
  defects:
    `Defects hold steady. verification: and on_red: are untouched, so CI still gates every ` +
    `merge and a red still unwinds clean. What broke is memory, not safety: outcomes stop ` +
    `landing on the track record, the steward re-argues the same finding ` +
    `${FINALE.relitigated} times (is a lockfile-only diff safe to skim?), and week ten is ` +
    `priced like week one. The bill is attention, not regressions.`,
  flat:
    `Flat is what the engine draws. Each clean merge nudged the class's track record, and the ` +
    `record set next week's review minutes — update: was the only stanza feeding it. Frozen at ` +
    `week one, this loop re-pays ${AMN_WEEK} minutes every week while the closing loop falls ` +
    `to ${WEEK10}. Ten weeks of that gap: ${FINALE.billMinutes} steward minutes.`,
};

const FORK2_RULE =
  "Loops that don't close aren't loops; they're fire-and-forget scripts that accumulate debt.";

/* ── The lab ───────────────────────────────────────────────────────────── */

const MODE_LABEL = {
  canonical: 'canonical · CI green',
  red: 'fork 1 · oracle red',
  amnesia: 'fork 2 · update: deleted',
};

export default function HelloLoop() {
  const reduced = usePrefersReducedMotion();
  const [mode, setMode] = useState('canonical');
  // Legible at rest: the bench mounts on the final frame of the canonical run.
  const [idx, setIdx] = useState(CANONICAL.steps.length - 1);
  const [playing, setPlaying] = useState(false);
  const [unlocked, setUnlocked] = useState(false);
  const [committed, setCommitted] = useState(null);

  const trace = mode === 'canonical' ? CANONICAL : mode === 'red' ? RED : AMNESIA;
  const last = trace.steps.length - 1;
  const revealed = mode !== 'amnesia' || committed !== null;

  useEffect(() => {
    if (!playing) return undefined;
    if (idx >= last) {
      setPlaying(false);
      if (mode === 'canonical') setUnlocked(true);
      return undefined;
    }
    const t = setTimeout(() => setIdx((i) => Math.min(last, i + 1)), 1100);
    return () => clearTimeout(t);
  }, [playing, idx, last, mode]);

  const step = () => {
    const next = Math.min(last, idx + 1);
    setIdx(next);
    if (mode === 'canonical' && next === last) setUnlocked(true);
  };
  const run = () => {
    if (reduced) {
      // Reduced motion: Run steps discretely to the final frame.
      setIdx(last);
      if (mode === 'canonical') setUnlocked(true);
      return;
    }
    if (idx >= last) setIdx(0);
    setPlaying(true);
  };
  const reset = () => {
    setPlaying(false);
    setIdx(0);
  };
  const switchMode = (m) => {
    setPlaying(false);
    const next = mode === m ? 'canonical' : m;
    setMode(next);
    const t = next === 'canonical' ? CANONICAL : next === 'red' ? RED : AMNESIA;
    setIdx(t.steps.length - 1); // each fork also lands legible: final frame first
  };

  const committedLabel = FORK2_OPTIONS.find((o) => o.id === committed)?.label;

  return (
    <LabFrame
      tag="LAB 01·A — HELLO, LOOP"
      register="mechanism"
      question="Fourteen lines claim to patch your dependencies while you sleep. What is each stanza buying, and what does it cost to delete one?"
      payoff={
        <>
          The artifact is the decision; the trace is its bill. Intact, the steward's weekly review
          cost falls from {WEEK1} to {WEEK10} minutes over ten weeks as the track record accrues.
          Delete the update: stanza and no single run looks any different, but the bill never falls:{' '}
          {AMN_WEEK} minutes a week forever, {FINALE.billMinutes} extra steward minutes in ten
          weeks. {FORK2_RULE}{' '}
          <Badge layer="W" note="§3.2 — the handbook's working principle, run" />
        </>
      }
      notes={[
        'The benchfile is notation, house style for the whole book, not a shipping config format.',
        `Review minutes are priced off one per-class trust scalar: 15 minutes a PR with no record, floored at 4, discounted as the record grows. Real stewards price risk on more than a number.`,
        'Tuned constants set the shape, not real thresholds: CI passes 92% of bumps, 5% of merges regress post-merge, trust gains 0.05 per clean merge and caps at 0.95.',
        `Both ten-week runs share seed ${SEED} and four proposals a week, so the only difference between the two curves is the deleted stanza.`,
      ]}
      cannotShow="whether these constants are your constants. The engine draws the shape of the amnesia bill, not its size; nothing here predicts a real repo's review minutes or pass rates."
      glass={GLASS}
    >
      <div className="mh-bench">
        <div>
          <span className="mh-kicker" style={{ display: 'block', marginBottom: 6 }}>
            The artifact · dependency-patch benchfile{' '}
            <Mark kind="made" note="constructed for teaching; Ch 14 shows the real one" />
          </span>
          <Artifact lines={benchfileLines(mode, hotLinesFor(mode, idx))} />
        </div>
        <div>
          <span className="mh-kicker" style={{ display: 'block', marginBottom: 6 }}>
            The run · seed {SEED} · {MODE_LABEL[mode]}
          </span>
          <div className="mh-trace">
            {mode !== 'amnesia' ? (
              <>
                <RunSnapshot steps={trace.steps} idx={idx} />
                <StepList steps={trace.steps} idx={idx} />
                {mode === 'red' && idx >= 3 ? <DivergenceStrip /> : null}
              </>
            ) : committed === null ? (
              <Commit
                prompt="You just deleted the only stanza that writes outcomes back into the terrain. Every weekly run still bumps, tests, and merges exactly as before. Ten weeks out, what has it cost?"
                options={FORK2_OPTIONS}
                onReveal={setCommitted}
              >
                {(id) => FORK2_FEEDBACK[id]}
              </Commit>
            ) : (
              <>
                <div className="mh-feedback">
                  <span className="mh-kicker" style={{ display: 'block', marginBottom: 6 }}>
                    You predicted · {committedLabel}
                  </span>
                  {FORK2_FEEDBACK[committed]}
                </div>
                <AmnesiaChart
                  closing={CLOSING_COST}
                  amnesiac={AMNESIAC_COST}
                  uptoWeek={AMNESIA_WEEK_AT_STEP[Math.min(idx, last)]}
                  billMinutes={FINALE.billMinutes}
                />
                <StepList steps={trace.steps} idx={idx} />
              </>
            )}
          </div>
        </div>
      </div>
      <div className="mh-controls" role="group" aria-label="Bench controls: Step, Run, Reset">
        <button
          type="button"
          className="mh-btn"
          onClick={step}
          disabled={!revealed || playing || idx >= last}
          aria-label="Step one stage forward"
        >
          Step
        </button>
        <button
          type="button"
          className="mh-btn mh-btn-primary"
          onClick={run}
          disabled={!revealed || playing}
          aria-label="Run the whole recorded trace"
        >
          Run
        </button>
        <button
          type="button"
          className="mh-btn"
          onClick={reset}
          disabled={!revealed || idx === 0}
          aria-label="Reset to the first stage"
        >
          Reset
        </button>
        <span className="mh-kicker" aria-live="polite">
          {mode === 'amnesia' ? 'step' : 'stage'} {Math.min(idx, last) + 1} of {last + 1}
        </span>
      </div>
      <div className="mh-controls" role="group" aria-label="Fork bar">
        <span className="mh-kicker">Fork</span>
        <button
          type="button"
          className="mh-chip"
          aria-pressed={mode === 'red'}
          disabled={!unlocked}
          onClick={() => switchMode('red')}
          title={unlocked ? undefined : 'Walk the canonical run first'}
        >
          1 · CI comes back red
        </button>
        <button
          type="button"
          className="mh-chip"
          aria-pressed={mode === 'amnesia'}
          disabled={!unlocked}
          onClick={() => switchMode('amnesia')}
          title={unlocked ? undefined : 'Walk the canonical run first'}
        >
          2 · delete the update: stanza
        </button>
        {!unlocked ? (
          <button
            type="button"
            onClick={() => setUnlocked(true)}
            className="mono"
            style={{
              background: 'none',
              border: 'none',
              padding: 0,
              fontSize: '10.5px',
              letterSpacing: '0.08em',
              color: 'var(--ink-faint)',
              textDecoration: 'underline',
              cursor: 'pointer',
            }}
          >
            forks open after one full pass — show me anyway
          </button>
        ) : null}
      </div>
    </LabFrame>
  );
}
